export const recheck = internalQuery({
  args: { reference: runtimeAuthorityReference, requirement: runtimeAuthorityRequirement },
  handler: async (ctx, args) => await recheckAuthority(ctx, args.reference, args.requirement),
});

function nonempty(value: string): void {
  if (!value.trim()) deny("INVALID_INPUT");
}

async function ensureScope(ctx: MutationCtx, tenantId: string, memorySpaceId?: string): Promise<ScopeRecord> {
  const existing = await ctx.db.query("runtimeAuthScopes")
    .withIndex("by_tenant_space", (q) => q.eq("tenantId", tenantId).eq("memorySpaceId", memorySpaceId)).unique();
  if (existing) {
    if (existing.deletedAt !== undefined) deny();
    return existing;
  }
  if (await createAuthorityReader(ctx).hasTombstone({ tenantId, memorySpaceId,
    resourceType: memorySpaceId === undefined ? "tenant" : "memorySpace", resourceId: memorySpaceId ?? tenantId })) deny();
  const scope = { tenantId, ...(memorySpaceId === undefined ? {} : { memorySpaceId }), epoch: 1, createdAt: Date.now() };
  await ctx.db.insert("runtimeAuthScopes", scope);
  return scope;
}

/** Trusted deployment operator only. No public self-provisioning, even with an admin claim. */
export const provision = internalMutation({
  args: {
    issuer: v.string(), subject: v.string(), actorKind: runtimeActorKind,
    metadataUserId: v.optional(v.string()), tenantId: v.string(), memorySpaceId: v.optional(v.string()),
    capabilities: v.array(runtimeCapability), resourceAccess: runtimeResourceAccess, expiresAt: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    [args.issuer, args.subject, args.tenantId].forEach(nonempty);
    if (args.memorySpaceId !== undefined) nonempty(args.memorySpaceId);
    if (args.metadataUserId !== undefined) nonempty(args.metadataUserId);
    if (args.capabilities.length === 0 || (args.resourceAccess === "space" && args.memorySpaceId === undefined)
      || (args.resourceAccess === "tenant" && args.memorySpaceId !== undefined)
      || (args.expiresAt !== undefined && (!Number.isFinite(args.expiresAt) || args.expiresAt <= Date.now()))) deny("INVALID_INPUT");
    const now = Date.now();
    const reader = createAuthorityReader(ctx);
    const tenant = await ensureScope(ctx, args.tenantId);
    const space = args.memorySpaceId === undefined ? undefined : await ensureScope(ctx, args.tenantId, args.memorySpaceId);
    let principal = await ctx.db.query("runtimeAuthPrincipals")
      .withIndex("by_issuer_subject", (q) => q.eq("issuer", args.issuer).eq("subject", args.subject)).unique();
    if (principal && (!active(principal) || principal.actorKind !== args.actorKind
      || principal.metadataUserId !== args.metadataUserId)) deny();
    if (!principal) {
      const id = await ctx.db.insert("runtimeAuthPrincipals", {
        issuer: args.issuer, subject: args.subject, actorKind: args.actorKind,
        ...(args.metadataUserId === undefined ? {} : { metadataUserId: args.metadataUserId }), version: 1, createdAt: now,
      });
      principal = await ctx.db.get("runtimeAuthPrincipals", id);
    }
    if (!principal) deny();
    let membership = await ctx.db.query("runtimeAuthMemberships")
      .withIndex("by_principal_tenant", (q) => q.eq("principalId", principal._id).eq("tenantId", args.tenantId)).unique();
    if (membership && !active(membership)) deny();
    if (!membership) {
      const id = await ctx.db.insert("runtimeAuthMemberships", {
        principalId: principal._id, tenantId: args.tenantId, version: 1, createdAt: now,
      });
      membership = await ctx.db.get("runtimeAuthMemberships", id);
    }
    if (!membership) deny();
    const previous = (await reader.listGrants(membership._id)).filter((grant) => grant.memorySpaceId === args.memorySpaceId);
    const capabilities = [...new Set(args.capabilities)].sort();
    const current = previous.filter((grant) => active(grant));
    if (current.length > 1) deny();
    if (current[0] && JSON.stringify([...current[0].capabilities].sort()) === JSON.stringify(capabilities)
      && current[0].resourceAccess === args.resourceAccess && current[0].expiresAt === args.expiresAt
      && current[0].tenantEpoch === tenant.epoch && current[0].memorySpaceEpoch === space?.epoch) {
      return await materialize(reader, principal, membership, current[0], { capability: capabilities[0]! }, now);
    }
    // Changing authority creates a new immutable grant generation and invalidates the old reference.
    for (const old of current) {
      const id = ctx.db.normalizeId("runtimeAuthGrants", old._id);
      if (!id) deny();
      await ctx.db.patch("runtimeAuthGrants", id, { revokedAt: now });
    }
    const id = await ctx.db.insert("runtimeAuthGrants", {
      principalId: principal._id, membershipId: membership._id, tenantId: args.tenantId,
      ...(args.memorySpaceId === undefined ? {} : { memorySpaceId: args.memorySpaceId, memorySpaceEpoch: space!.epoch }),
      tenantEpoch: tenant.epoch, capabilities, resourceAccess: args.resourceAccess,
      version: Math.max(0, ...previous.map((grant) => grant.version)) + 1, createdAt: now,
      ...(args.expiresAt === undefined ? {} : { expiresAt: args.expiresAt }),
    });
    const grant = await ctx.db.get("runtimeAuthGrants", id);
    if (!grant) deny();
    return await materialize(reader, principal, membership, grant, { capability: capabilities[0]! }, now);
  },
});

export const revokeGrant = internalMutation({
  args: { grantId: v.id("runtimeAuthGrants") },
  handler: async (ctx, args) => {
    const grant = await ctx.db.get("runtimeAuthGrants", args.grantId);
    if (grant && grant.revokedAt === undefined) await ctx.db.patch("runtimeAuthGrants", grant._id, { revokedAt: Date.now() });
  },
});
export const revokeMembership = internalMutation({
  args: { membershipId: v.id("runtimeAuthMemberships") },
  handler: async (ctx, args) => {
    const membership = await ctx.db.get("runtimeAuthMemberships", args.membershipId);
    if (membership && membership.revokedAt === undefined) await ctx.db.patch("runtimeAuthMemberships", membership._id,
      { revokedAt: Date.now(), version: membership.version + 1 });
  },
});
export const deletePrincipal = internalMutation({
  args: { principalId: v.id("runtimeAuthPrincipals") },
  handler: async (ctx, args) => {
    const principal = await ctx.db.get("runtimeAuthPrincipals", args.principalId);
    if (principal && principal.deletedAt === undefined) await ctx.db.patch("runtimeAuthPrincipals", principal._id,
      { deletedAt: Date.now(), version: principal.version + 1 });
  },
});
export const deleteScope = internalMutation({
  args: { tenantId: v.string(), memorySpaceId: v.optional(v.string()) },
  handler: async (ctx, args) => {
    const scope = await ctx.db.query("runtimeAuthScopes")
      .withIndex("by_tenant_space", (q) => q.eq("tenantId", args.tenantId).eq("memorySpaceId", args.memorySpaceId)).unique();
    if (scope && scope.deletedAt === undefined) await ctx.db.patch("runtimeAuthScopes", scope._id,
      { deletedAt: Date.now(), epoch: scope.epoch + 1 });
    const key = { ...args, resourceType: args.memorySpaceId === undefined ? "tenant" as const : "memorySpace" as const,
      resourceId: args.memorySpaceId ?? args.tenantId };
    if (!await createAuthorityReader(ctx).hasTombstone(key)) await ctx.db.insert("runtimeAuthTombstones", { ...key, deletedAt: Date.now() });
  },
});
export const tombstoneResource = internalMutation({
  args: { tenantId: v.string(), memorySpaceId: v.optional(v.string()), resourceType: runtimeResourceType, resourceId: v.string() },
  handler: async (ctx, args) => {
    nonempty(args.tenantId); nonempty(args.resourceId);
    if (!await createAuthorityReader(ctx).hasTombstone(args)) await ctx.db.insert("runtimeAuthTombstones", { ...args, deletedAt: Date.now() });
  },
});

/** Scoped data selections for alternate public endpoints. Caller labels are never grants. */
import { ConvexError } from "convex/values";
import { makeFunctionReference } from "convex/server";
import type { FunctionReference } from "convex/server";
import type { ActionCtx, MutationCtx, QueryCtx } from "./_generated/server";
import type { Doc } from "./_generated/dataModel";
import type { RuntimeAuthority, RuntimeAuthorityReference, RuntimeAuthorityRequirement, RuntimeCapability, RuntimeResource } from "./_cortex/shared/auth/verified";
import type { SourceLineage } from "./_cortex/shared/domain/contracts";
import { normalizeSourceText, semanticHash } from "./_cortex/shared/domain/profile";
import { assertSourceLineage } from "./_cortex/shared/domain/sources";
import { assertResourceScope, createAuthorityReader, recheckAuthority, requireAuthority, resolveAuthority, resolveAuthorityReference } from "./runtimeAuth";
import type { AuthorityReader, GrantRecord } from "./runtimeAuth";

export type ScopedDataAuthority = RuntimeAuthority & { memorySpaceId: string; memorySpaceEpoch: number };
type ReadCtx = Pick<QueryCtx, "db">;
type DataTable = "memories" | "facts";
type DataRow = Doc<"memories"> | Doc<"facts">;
type Capability = "read" | "write";
export function dataDenied(code = "FORBIDDEN", message = "Access denied"): never {
  throw new ConvexError({ version: 1, code, message, retryable: false, outcome: "not_dispatched" });
}
function concrete(authority: RuntimeAuthority): ScopedDataAuthority {
  if (!authority.memorySpaceId || authority.memorySpaceEpoch === undefined) dataDenied();
  return { ...authority, memorySpaceId: authority.memorySpaceId, memorySpaceEpoch: authority.memorySpaceEpoch };
}
/** Every external query execution reloads grants; omitted selectors derive one trusted concrete scope. */
export async function requireDataAuthority(ctx: Pick<QueryCtx, "auth" | "db">,
  selectors: { tenantId?: string; memorySpaceId?: string }, capability: RuntimeCapability): Promise<ScopedDataAuthority> {
  const authority = await requireAuthority(ctx, { capability, tenantId: selectors.tenantId, memorySpaceId: selectors.memorySpaceId });
  if (authority.memorySpaceId) return concrete(authority);
  const spaces = await ctx.db.query("runtimeAuthScopes").withIndex("by_tenant_space", q => q.eq("tenantId", authority.tenantId)).collect();
  const eligible = spaces.filter(space => space.memorySpaceId && space.deletedAt === undefined);
  if (eligible.length !== 1) dataDenied();
  return concrete(await requireAuthority(ctx, { capability, tenantId: authority.tenantId, memorySpaceId: eligible[0].memorySpaceId }));
}
export async function recheckDataAuthority(ctx: ReadCtx, reference: RuntimeAuthorityReference,
  capability: RuntimeCapability): Promise<ScopedDataAuthority> {
  return concrete(await recheckAuthority(ctx, reference, { capability, tenantId: reference.tenantId, memorySpaceId: reference.memorySpaceId }));
}
/** Explicit typed names of actual internal registrations, until coordinator-owned codegen. */
function internalQueryRef<Args extends Record<string, unknown>, Result>(name: string) {
  return makeFunctionReference<"query", Args, Result>(name) as unknown as FunctionReference<"query", "internal", Args, Result>;
}
export const dataAuthReferences = {
  authorize: internalQueryRef<{ requirement: RuntimeAuthorityRequirement }, RuntimeAuthority>("runtimeAuth:authorize"),
  recheck: internalQueryRef<{ reference: RuntimeAuthorityReference; requirement: RuntimeAuthorityRequirement }, RuntimeAuthority>("runtimeAuth:recheck"),
};
/** Exact RPC shape: authorization metadata stays local; the server reloads it. */
export function dataAuthorityReference(authority: RuntimeAuthorityReference): RuntimeAuthorityReference {
  return {
    principalId: authority.principalId, principalVersion: authority.principalVersion,
    membershipId: authority.membershipId, membershipVersion: authority.membershipVersion,
    grantId: authority.grantId, grantVersion: authority.grantVersion,
    tenantId: authority.tenantId, tenantEpoch: authority.tenantEpoch,
    ...(authority.memorySpaceId !== undefined ? { memorySpaceId: authority.memorySpaceId } : {}),
    ...(authority.memorySpaceEpoch !== undefined ? { memorySpaceEpoch: authority.memorySpaceEpoch } : {}),
  };
}
/** runQuery inherits Convex-verified auth. No public reference or JWT argument establishes identity. */
export async function requireActionDataAuthority(ctx: Pick<ActionCtx, "runQuery">,
  selectors: { tenantId?: string; memorySpaceId?: string }, capability: Capability): Promise<ScopedDataAuthority> {
  return concrete(await ctx.runQuery(dataAuthReferences.authorize, { requirement: { capability,
    tenantId: selectors.tenantId, memorySpaceId: selectors.memorySpaceId } }));
}
export async function recheckActionDataAuthority(ctx: Pick<ActionCtx, "runQuery">,
  reference: RuntimeAuthorityReference, capability: Capability): Promise<void> {
  await ctx.runQuery(dataAuthReferences.recheck, { reference: dataAuthorityReference(reference), requirement: { capability,
    tenantId: reference.tenantId, memorySpaceId: reference.memorySpaceId } });
}
/** Actor metadata may narrow/filter requests, but public writes cannot impersonate another actor. */
export function bindDataActor(authority: RuntimeAuthority, label?: string): string {
  if (label !== undefined && label !== authority.userId) dataDenied();
  return authority.userId;
}
export function rejectUnqualifiedEmbedding(embedding?: readonly number[]): void {
  if (embedding !== undefined) dataDenied("PROFILE_NOT_READY", "Caller embeddings lack qualified source/profile provenance; use the modern profiled runtime retrieval adapter");
}
function resource(row: DataRow): RuntimeResource {
  return { resourceType: "memoryId" in row ? "memory" : "fact", resourceId: "memoryId" in row ? row.memoryId : row.factId,
    tenantId: row.tenantId, memorySpaceId: row.memorySpaceId, ownerPrincipalId: row.ownerPrincipalId };
}
export async function assertOwnedResource(ctx: ReadCtx, authority: ScopedDataAuthority, capability: RuntimeCapability,
  target: RuntimeResource): Promise<void> {
  // Missing ownership never becomes adoption, including cross-principal grants.
  if (!target.ownerPrincipalId) dataDenied();
  assertResourceScope(authority, target);
  await recheckAuthority(ctx, authority, { capability, tenantId: authority.tenantId, memorySpaceId: authority.memorySpaceId, resource: target });
}
function sameLineage(a: SourceLineage, b: SourceLineage): boolean {
  return a.sourceId === b.sourceId && a.sourceEventId === b.sourceEventId && a.sourceRevision === b.sourceRevision
    && a.role === b.role && a.trust === b.trust
    && ("operationId" in a ? a.operationId : undefined) === ("operationId" in b ? b.operationId : undefined);
}
/** Private server witness; public validators/metadata never accept it. */
export type CanonicalSourceWitness = Readonly<Doc<"runtimeMemorySources">>;
/** Private linked admissions follow retained source objects across array concatenation. */
type LinkedWitness = {
  table: "conversations" | "immutable" | "mutable" | DataTable;
  target: RuntimeResource; storageId: string;
  selectors: { type?: string; id?: string; namespace?: string; key?: string };
  expectedVersion?: number; messageIds?: readonly string[]; conversationId?: string; dataBinding?: string;
};
function linkedDataBinding(row: DataRow): string {
  return JSON.stringify({ lineage: row.lineage, conversationRef: "conversationRef" in row ? row.conversationRef : undefined,
    factsRef: "factsRef" in row ? row.factsRef : undefined, immutableRef: "immutableRef" in row ? row.immutableRef : undefined,
    mutableRef: "mutableRef" in row ? row.mutableRef : undefined, sourceRef: "sourceRef" in row ? row.sourceRef : undefined });
}
const operationLinks = new WeakMap<CanonicalSourceWitness[], LinkedWitness[]>();
const sourceLinks = new WeakMap<CanonicalSourceWitness, LinkedWitness[]>();
const sourcePermissions = new WeakMap<CanonicalSourceWitness, ConversationPermission>();
function retainedLinks(witnesses: CanonicalSourceWitness[]): LinkedWitness[] {
  let links = operationLinks.get(witnesses);
  if (!links) { links = []; operationLinks.set(witnesses, links); }
